// AircraftRegistryService — data layer for the ToAviate-admin Aircraft
// Registry sync (CAA G-INFO → our `aircraft` REFERENCE table). This module
// only ever touches the reference/autocomplete database — club fleet rows in
// `planes` are never read or written by a sync. There is deliberately no
// delete endpoint anywhere in this feature.
// See FRONTEND_AIRCRAFT_REGISTRY_SYNC_GUIDE.md.
//
// Conventions (same as trackerCommerceService / gclMonitorService):
//  - app.factory + $inject, every call .then(handleSuccess, handleError)
//  - success responses come back as the raw body ({ success:true, ... });
//    errors RESOLVE (never reject) with { success:false, message, status }
//  - the apiUrlInterceptor in app.js prefixes '/api/v1/...' automatically
app.factory('AircraftRegistryService', AircraftRegistryService);
    AircraftRegistryService.$inject = ['$http', '$location'];
    function AircraftRegistryService($http, $location) {
        var base = '/api/v1';
        var s = {};

        function qs(params) {
            if (!params) { return ''; }
            var parts = [];
            for (var k in params) {
                if (params.hasOwnProperty(k) && params[k] !== null && params[k] !== undefined && params[k] !== '') {
                    parts.push(encodeURIComponent(k) + '=' + encodeURIComponent(params[k]));
                }
            }
            return parts.length ? ('?' + parts.join('&')) : '';
        }

        // ── Status + runs ─────────────────────────────────────────────────
        s.Status     = function()        { return $http.get(base + '/aircraft_registry/status').then(handleSuccess, handleError); };
        s.GetRun     = function(id)      { return $http.get(base + '/aircraft_registry/run/' + id).then(handleSuccess, handleError); };
        s.Runs       = function()        { return $http.get(base + '/aircraft_registry/runs').then(handleSuccess, handleError); };

        // Creates a STAGED run — nothing is scraped until Start. recaptcha_keys
        // is optional (empty = token-free; the CAA API currently needs none).
        s.CreateRun  = function(recaptcha_keys) { return $http.post(base + '/aircraft_registry/run', { recaptcha_keys: recaptcha_keys || '' }).then(handleSuccess, handleError); };
        s.StartRun   = function(id)      { return $http.post(base + '/aircraft_registry/run/' + id + '/start', {}).then(handleSuccess, handleError); };
        s.PauseRun   = function(id)      { return $http.post(base + '/aircraft_registry/run/' + id + '/pause', {}).then(handleSuccess, handleError); };
        // Cancel keeps already-applied batches; nothing rolls back.
        s.CancelRun  = function(id)      { return $http.post(base + '/aircraft_registry/run/' + id + '/cancel', {}).then(handleSuccess, handleError); };
        // Advances ONE batch in the foreground and returns the updated run.
        // Looped (~every 2–3s) while the tab is open for a faster apply; the
        // 15-min cron does the same unattended when the tab is closed.
        s.ProcessRun = function(id)      { return $http.post(base + '/aircraft_registry/run/' + id + '/process', {}).then(handleSuccess, handleError); };

        // ── Advisories (changes held because the reg is club-assigned) ────
        s.Advisories      = function(status) { return $http.get(base + '/aircraft_registry/advisories' + qs({ status: status })).then(handleSuccess, handleError); };
        // Apply = update the REFERENCE row only (never the club's plane row).
        s.ApplyAdvisory   = function(id) { return $http.post(base + '/aircraft_registry/advisories/' + id + '/apply', {}).then(handleSuccess, handleError); };
        // Dismiss = keep our reference data as-is.
        s.DismissAdvisory = function(id) { return $http.post(base + '/aircraft_registry/advisories/' + id + '/dismiss', {}).then(handleSuccess, handleError); };

        // ── Shared reference data ─────────────────────────────────────────
        s.enums = {
            runStates:        ['staged', 'running', 'paused', 'done', 'cancelled', 'error'],
            phases:           ['search', 'details', 'dereg'],
            advisoryStatuses: ['pending', 'applied', 'dismissed']
        };

        s.badges = {
            run: {
                staged: 'trk-badge--blue', running: 'trk-badge--violet', paused: 'trk-badge--amber',
                done: 'trk-badge--green', cancelled: 'trk-badge--grey', error: 'trk-badge--red'
            },
            advisory: {
                pending: 'trk-badge--amber', applied: 'trk-badge--green', dismissed: 'trk-badge--grey'
            }
        };

        return s;

        function handleSuccess(res) { return res.data; }
        // Preserves body keys (e.g. error:'RUN_IN_PROGRESS' + its run object)
        // so controllers can branch on them even when the HTTP status errored.
        function handleError(res) {
            if (res && res.status == 401) { $location.path('/login'); }
            var body = (res && res.data && typeof res.data === 'object') ? res.data : {};
            var out = { status: res && res.status };
            for (var k in body) { if (body.hasOwnProperty(k)) { out[k] = body[k]; } }
            out.success = false;
            if (!out.message) { out.message = out.error || 'Request failed'; }
            return out;
        }
    }

// ═══════════════════════════════════════════════════════════════════
//  AirfieldAdminService
//  ToAviate super-admin management of the global airfield database:
//    – Dashboard / coverage status
//    – Import a country or a map area from OurAirports
//    – Review queue (co-located duplicates + auto-imported rows)
//    – Manual CRUD on individual airfields
//    – Search over the existing airfield table
//  Backend contract: FRONTEND_AIRFIELD_IMPORT_ADMIN_GUIDE.md
// ═══════════════════════════════════════════════════════════════════

app.factory('AirfieldAdminService', AirfieldAdminService);

AirfieldAdminService.$inject = ['$http', '$location', 'EnvConfig'];
function AirfieldAdminService($http, $location, EnvConfig) {

    // The public airfield search endpoints (/airfields/*) use the same relaxed
    // headers as the bookout form rather than the admin session headers.
    var siteOrigin = window.location.origin;
    var airfieldSearchHeaders = {
        'Api-Key': EnvConfig.getApiKey(),
        'Authorization': 'Basic aGVyZWJlOmRyYWdvbnM=',
        'X-Origin': siteOrigin,
        'X-Referer': siteOrigin + '/'
    };

    var service = {};

    service.GetStatus       = GetStatus;
    service.ImportCountry   = ImportCountry;
    service.ImportArea      = ImportArea;
    service.FillElevations  = FillElevations;
    service.GetReview       = GetReview;
    service.ApproveReview   = ApproveReview;
    service.DismissReview   = DismissReview;
    service.CreateAirfield  = CreateAirfield;
    service.UpdateAirfield  = UpdateAirfield;
    service.DeleteAirfield  = DeleteAirfield;
    service.SearchAirfields = SearchAirfields;
    service.GetAirfield     = GetAirfield;
    service.MergeIntoExisting = MergeIntoExisting;

    // The fields a location_dup candidate can contribute to an existing row,
    // in the order they're shown in the compare card.
    service.merge_fields = MERGE_FIELDS;

    // Reference data used by the views (country names, airfield types).
    service.countries = COUNTRIES;
    service.af_types  = AF_TYPES;
    service.countryName = countryName;

    return service;

    // ── Dashboard ──
    function GetStatus() {
        return $http.get('/api/v1/airfield_import/status').then(handleSuccess, handleError2);
    }

    // ── Imports ──
    function ImportCountry(iso) {
        return $http.post('/api/v1/airfield_import/country', { iso: iso })
            .then(handleSuccess, handleError2);
    }

    function ImportArea(lat, lon, box) {
        return $http.post('/api/v1/airfield_import/area', { lat: lat, lon: lon, box: box })
            .then(handleSuccess, handleError2);
    }

    // ── Elevations ──
    // Fill blank elevations: OurAirports where it has a figure, terrain DEM for
    // the rest. NOTE: the terrain provider is throttled to ~1 req/sec, so a run
    // takes MINUTES (our first real run: ~350 s). Deliberately no `timeout` —
    // $http would abort a healthy request. Resumable and idempotent: if
    // `remaining > 0`, calling again picks up where it left off.
    function FillElevations(limit, usedByFlights) {
        return $http.post('/api/v1/airfield_import/elevations', {
            limit:           limit || 300,
            used_by_flights: !!usedByFlights
        }).then(handleSuccess, handleError2);
    }

    // ── Review queue ──
    function GetReview(status) {
        return $http.get('/api/v1/airfield_import/review?status=' + (status || 'pending'))
            .then(handleSuccess, handleError2);
    }

    function ApproveReview(id) {
        return $http.post('/api/v1/airfield_import/review/' + id + '/approve', {})
            .then(handleSuccess, handleError2);
    }

    function DismissReview(id) {
        return $http.post('/api/v1/airfield_import/review/' + id + '/dismiss', {})
            .then(handleSuccess, handleError2);
    }

    // ── Manual CRUD ──
    function CreateAirfield(airfield) {
        return $http.post('/api/v1/airfield_import/airfield', airfield)
            .then(handleSuccess, handleError2);
    }

    function UpdateAirfield(id, airfield) {
        return $http.put('/api/v1/airfield_import/airfield/' + id, airfield)
            .then(handleSuccess, handleError2);
    }

    function DeleteAirfield(id) {
        return $http.delete('/api/v1/airfield_import/airfield/' + id)
            .then(handleSuccess, handleError2);
    }

    // ── Search (existing public endpoints) ──
    function SearchAirfields(query) {
        return $http.get('/api/v1/airfields/all/' + encodeURIComponent(query),
            { headers: airfieldSearchHeaders }).then(handleSuccess, handleError2);
    }

    // Returns { success, airfield: {…all columns…} }.
    function GetAirfield(id) {
        return $http.get('/api/v1/airfields/' + id, { headers: airfieldSearchHeaders })
            .then(handleSuccess, handleError2);
    }

    // ── Merge a review candidate INTO the existing airfield ──
    // Writes the ticked fields onto the row we already have (keeping its id, so
    // every flight/booking pointing at it stays intact) and settles the queue
    // item — atomically, server-side. `fields` is the patch: only what the admin
    // ticked. Returns { success, airfield_id, updated }.
    function MergeIntoExisting(reviewId, fields) {
        return $http.post('/api/v1/airfield_import/review/' + reviewId + '/merge',
            { fields: fields }).then(handleSuccess, handleError2);
    }

    // ── Helpers ──
    function countryName(code) {
        if (!code) { return ''; }
        var c = COUNTRIES_BY_CODE[String(code).toUpperCase()];
        return c ? c.name : code;
    }

    function handleSuccess(res) {
        return res.data;
    }

    function handleError2(res) {
        if (res.status == 401) { $location.path('/login'); }
        return { success: false, message: res.data, status: res.status };
    }
}

